// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {StaxLPStaking} from "../src/StaxLPStaking.sol";

contract InvMutTest is Test {
    StaxLPStaking c;
    function setUp() public { c = new StaxLPStaking(address(this), address(this)); }
    function testFuzz_property(bool renounceFirst) public {
        if (renounceFirst) {
            vm.prank(address(this));
            c.renounceOwnership();
        }
        address actualOwner = c.owner();
        if (renounceFirst) {
            assertTrue(actualOwner == address(0));
        } else {
            assertTrue(actualOwner == address(this));
        }
    }
}
